package pe.com.asistencia.employee.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import pe.com.asistencia.employee.domain.Employee; import pe.com.asistencia.employee.repository.EmployeeRepository; import pe.com.asistencia.security.repository.UserRepository; import pe.com.asistencia.security.service.SupervisorScopeService; import java.time.*; import java.util.List;
@RestController @RequestMapping("/api/v1/employees") @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')")
public class EmployeeController {
 private final EmployeeRepository employees; private final UserRepository users; private final SupervisorScopeService scopes; public EmployeeController(EmployeeRepository employees,UserRepository users,SupervisorScopeService scopes){this.employees=employees;this.users=users;this.scopes=scopes;}
 @GetMapping public List<Response> list(Authentication auth){var allowed=scopes.employeeIds(auth,LocalDate.now());return employees.findAll().stream().filter(e->allowed.contains(e.getId())).map(Response::of).toList();} @GetMapping("/{id}") public Response get(Authentication auth,@PathVariable Long id){if(!scopes.canAccess(auth,id,LocalDate.now()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"OUTSIDE_SUPERVISOR_SCOPE");return Response.of(find(id));}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public Response create(@Valid @RequestBody CreateRequest r){if(employees.existsByCodeIgnoreCase(r.code())||employees.existsByDocumentTypeIgnoreCaseAndDocumentNumber(r.documentType(),r.documentNumber()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Código o documento duplicado");var user=r.userId()==null?null:users.findById(r.userId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Usuario no encontrado"));return Response.of(employees.save(new Employee(r.code(),r.documentType(),r.documentNumber(),r.firstNames(),r.lastNames(),r.photoUrl(),r.email(),r.phone(),r.hireDate(),user)));}
 @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public Response update(@PathVariable Long id,@Valid @RequestBody UpdateRequest r){var e=find(id);e.update(r.firstNames(),r.lastNames(),r.photoUrl(),r.email(),r.phone(),r.terminationDate(),r.active());return Response.of(employees.save(e));}
 private Employee find(Long id){return employees.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Empleado no encontrado"));}
 public record CreateRequest(@NotBlank String code,@NotBlank String documentType,@NotBlank String documentNumber,@NotBlank String firstNames,@NotBlank String lastNames,@Size(max=1000) String photoUrl,@Email String email,String phone,@NotNull LocalDate hireDate,Long userId){} public record UpdateRequest(@NotBlank String firstNames,@NotBlank String lastNames,@Size(max=1000) String photoUrl,@Email String email,String phone,LocalDate terminationDate,boolean active){} public record Response(Long id,Long userId,String code,String documentType,String documentNumber,String firstNames,String lastNames,String photoUrl,String email,String phone,LocalDate hireDate,LocalDate terminationDate,boolean active){static Response of(Employee e){return new Response(e.getId(),e.getUser()==null?null:e.getUser().getId(),e.getCode(),e.getDocumentType(),e.getDocumentNumber(),e.getFirstNames(),e.getLastNames(),e.getPhotoUrl(),e.getEmail(),e.getPhone(),e.getHireDate(),e.getTerminationDate(),e.isActive());}}
}
